      ro: ["O statuie gigantică de marmură a lui Buddha șezând pe dealul Nakkerd din Phuket, vizibilă de oriunde din sudul Phuketului.", "Se află pe teritoriul Regatului Thailandei.", "Este modelat de climatul musonic din Asia de Sud-Est."],
      en: ["A giant seated marble Buddha statue on Nakkerd Hill in Phuket, visible from anywhere in the south of Phuket.", "Located within the Kingdom of Thailand.", "Shaped by the monsoon climate of Southeast Asia."],
      es: ["Una enorme estatua de Buda sentado de mármol en la colina Nakkerd en Phuket, visible desde cualquier parte del sur de Phuket.", "Ubicado en el territorio del Reino de Tailandia.", "Caracterizado por el clima monzónico del sudeste asiático."],
      pt: ["Uma enorme estátua de Buda sentado de mármore na colina Nakkerd em Phuket, visível de qualquer parte do sul de Phuket.", "Localizado no território do Reino da Tailândia.", "Caracterizado pelo clima de monções do sudeste asiático."],
      fr: ["Une immense statue de Bouddha assis en marbre sur la colline de Nakkerd à Phuket, visible de partout dans le sud de Phuket.", "Situé sur le territoire du Royaume de Thaïlande.", "Caractérisé par le climat de mousson de l'Asie du Sud-Est."],
