      hu: ["Hasonlít a laoszi Buddha Parkhoz, amelyet ugyanaz a művész alkotott.", "Több mint 100 szobrot tartalmaz.", "A legmagasabb szobor 25 méter magas.", "Szürreális és egyedi hely."],
