      es: ["Similar al Parque de Buda en Laos, creado por el mismo artista.", "Contiene más de 100 esculturas.", "La escultura más alta tiene 25 metros de altura.", "Un lugar surrealista y único."],
      pt: ["Semelhante ao Parque de Buda no Laos, criado pelo mesmo artista.", "Contém mais de 100 esculturas.", "A escultura mais alta tem 25 metros de altura.", "Um local surreal e único."],
      fr: ["Similaire au parc du Bouddha au Laos, créé par le même artiste.", "Contient plus de 100 sculptures.", "La plus haute sculpture mesure 25 mètres de haut.", "Un lieu surréaliste et unique."],
