      pt: ["A altitude é de 2.565 metros.", "As temperaturas podem estar perto do ponto de congelação na estação fria.", "Um curto trilho natural percorre a floresta do cume.", "Stupas dedicadas ao rei e à rainha estão localizadas perto do cume."],
