    descriptionAdvanced: {
      de: "Gipfel des Doi Inthanon ist ein bemerkenswertes Element der thailändischen Geografie und Kultur. Der höchste Punkt in Thailand, gelegen im Nationalpark Doi Inthanon. Der Gipfel ist mit einem Wald bedeckt und beherbergt ein Denkmal für den letzten König von Chiang Mai. Die Höhe beträgt 2.565 Meter. Die Temperaturen können in der kühlen Jahreszeit nahe dem Gefrierpunkt liegen. Ein kurzer Naturlehrpfad führt durch den Gipfelwald. Dieses Wahrzeichen ist Teil des kulturellen Erbes Thailands, oft verbunden mit buddhistischen Tempeln, Wats und königlichen Bauten. Wie viele bedeutende Orte in Thailand vereint dieser Ort regionale Eigenheiten mit dem Erbe von Chao Phraya, Mekong und buddhistischer Tradition. Damit trägt dieser Ort zum vielseitigen Profil Thailands zwischen Andamanenküste, Reisfeldern und tropischen Wäldern bei.",
      hu: "A(z) Doi Inthanon csúcs a thaiföldi földrajz és kultúra figyelemre méltó eleme. Thaiföld legmagasabb pontja, a Doi Inthanon Nemzeti Parkban található. A csúcsot erdő borítja, és Csiangmaj utolsó királyának emlékműve található itt. Magassága 2565 méter. A hőmérséklet a hűvös évszakban fagypont közelébe süllyedhet. Egy rövid tanösvény vezet át a csúcson lévő erdőn. Ez a nevezetesség Thaiföld kulturális örökségének része, gyakran buddhista templomokhoz, watokhoz és királyi épületekhez kötődik. Thaiföld számos jelentős helyszínéhez hasonlóan ez is ötvözi a regionális sajátosságokat a Chao Phraya, a Mekong és a buddhista hagyomány örökségével. Ezzel a helyszín hozzájárul Thaiföld sokszínű arculatához, az Andamán-tenger partjai, a rizsföldek és a trópusi erdők között.",
      ro: "Vârful Doi Inthanon este un element remarcabil al geografiei și culturii thailandeze. Cel mai înalt punct din Thailanda, situat în Parcul Național Doi Inthanon. Vârful este acoperit de o pădure și găzduiește un memorial al ultimului rege din Chiang Mai. Altitudinea este de 2.565 de metri. Temperaturile pot scădea aproape de îngheț în sezonul rece. Un scurt traseu natural trece prin pădurea de pe vârf. Acest reper face parte din patrimoniul cultural al Thailandei, adesea legat de templele budiste, wat-uri și construcții regale. Asemenea multor locuri importante din Thailanda, acesta îmbină particularitățile regionale cu moștenirea fluviilor Chao Phraya, Mekong și a tradiției budiste. Astfel, acest loc contribuie la profilul variat al Thailandei, între coasta Andaman, câmpurile de orez și pădurile tropicale.",
      en: "Doi Inthanon Summit is a remarkable feature of the geography and culture of Thailand. The highest point in Thailand, located in Doi Inthanon National Park. The summit is covered in forest and hosts a memorial to the last king of Chiang Mai. The elevation is 2,565 meters. Temperatures can drop near freezing in the cool season. A short nature trail goes through the summit forest. This landmark is part of the cultural heritage of Thailand, often linked to Buddhist temples, wats and royal architecture. Like many notable places in Thailand, it combines regional character with the legacy of the Chao Phraya, the Mekong and Buddhist tradition. Thus, this place contributes to the diverse profile of Thailand, between the Andaman coast, rice paddies and tropical forests.",
      es: "La cima del Doi Inthanon es un elemento notable de la geografía y cultura tailandesa. El punto más alto de Tailandia, situado en el Parque Nacional Doi Inthanon. La cima está cubierta de bosque y alberga un monumento al último rey de Chiang Mai. La altura es de 2.565 metros. Las temperaturas pueden estar cerca del punto de congelación en la estación fría. Un corto sendero natural recorre el bosque de la cima. Este hito es parte del patrimonio cultural de Tailandia, a menudo relacionado con templos budistas, wats y edificios reales. Como muchos lugares importantes en Tailandia, este sitio combina peculiaridades regionales con el patrimonio de Chao Phraya, el Mekong y la tradición budista. Así, este lugar contribuye al perfil versátil de Tailandia entre la costa de Andamán, arrozales y bosques tropicales.",
      pt: "O cume do Doi Inthanon é um elemento notável da geografia e cultura tailandesa. O ponto mais alto da Tailândia, situado no Parque Nacional Doi Inthanon. O cume está coberto de floresta e abriga um monumento ao último rei de Chiang Mai. A altitude é de 2.565 metros. As temperaturas podem estar perto do ponto de congelação na estação fria. Um curto trilho natural percorre a floresta do cume. Este marco é parte do património cultural da Tailândia, frequentemente relacionado com templos budistas, wats e edifícios reais. Como muitos locais importantes na Tailândia, este local combina características regionais com a herança de Chao Phraya, do Mekong e da tradição budista. Assim, este local contribui para o perfil versátil da Tailândia entre a costa de Andaman, arrozais e florestas tropicais.",
      fr: "Le sommet du Doi Inthanon est un élément remarquable de la géographie et de la culture thaïlandaise. Le point culminant de la Thaïlande, situé dans le parc national de Doi Inthanon. Le sommet est couvert de forêts et abrite un monument au dernier roi de Chiang Mai. L'altitude est de 2 565 mètres. Les températures peuvent être proches du point de congélation pendant la saison fraîche. Un court sentier naturel traverse la forêt du sommet. Ce monument fait partie du patrimoine culturel de la Thaïlande, souvent lié aux temples bouddhistes, aux wats et aux bâtiments royaux. Comme beaucoup de lieux importants en Thaïlande, ce site allie particularités régionales et héritage du Chao Phraya, du Mékong et de la tradition bouddhiste. Ainsi, ce lieu contribue au profil polyvalent de la Thaïlande entre la côte d'Andaman, les rizières et les forêts tropicales.",
    },
