      pt: ["O ponto mais alto da Tailândia, situado no Parque Nacional Doi Inthanon. O cume está coberto de floresta e abriga um monumento ao último rei de Chiang Mai.", "Localizado no território do Reino da Tailândia.", "Caracterizado pelo clima de monções do sudeste asiático."],
      fr: ["Le point culminant de la Thaïlande, situé dans le parc national de Doi Inthanon. Le sommet est couvert de forêts et abrite un monument au dernier roi de Chiang Mai.", "Situé sur le territoire du Royaume de Thaïlande.", "Caractérisé par le climat de mousson de l'Asie du Sud-Est."],
